            for (const [j, y] of g2[k]) {
                ans[i][j] += x * y;
            }
        }
    }
    return ans;
}

class Solution:
    def multiply(self, A, B):
        """
        :type A: List[List[int]]
        :type B: List[List[int]]
        :rtype: List[List[int]]
        """
        rowA, colA, colB = len(A), len(A[0]), len(B[0])
        res = [[0 for i in range(colB)] for j in range(rowA)]

        for i in range(rowA):
            for j in range(colA):
                if A[i][j] != 0:
                    for k in range(colB):
                        if B[j][k] != 0:
                            res[i][k] += A[i][j] * B[j][k]
        return res


